INSERT INTO feature VALUES('running-programs','runtime','Running programs',NULL,'implemented','ordinary',NULL,'`gandr run` checks a source, focuses it into the command IL, runs the `main` it declares natively or on the portable executor and reads the answer back. Each run of an invocation holds its code-word jumps within `--run-budget`, and a run that spends the count stops and names it; without the flag, a run of `check`, `test` or `run` has no budget, and a run of `lsp` or `serve` takes the server''s budget of 2^24 jumps.','surface-dispatcher core-sequent runtime-emitter','corpus/model/modules/functor-pair.gandr','corpus/model/modules/functor-pair.gandr',NULL);
